head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[video > P > autoplay]<br/>Video 컴포넌트의 동영상을 자동으로 재생할지 설정합니다.",
    "validation" : [
        "Chrome 등 대부분의 최신 브라우저는 소리가 포함된 동영상의 자동 재생을 기본적으로 차단합니다.",
        "autoplay 설정 시, 화면이 로딩되면 동영상을 자동으로 재생합니다.",
        "빈 문자열('') 을 설정해도 자동으로 재생됩니다.",
        "브라우저의 보안/사용성 정책에 의해 소리가 포함된 동영상의 자동 재생이 차단될 수 있습니다.",
        "muted 속성을 설정하면 동영상의 자동 재생이 허용될 수 있습니다.",
        "Video 컴포넌트는 autoplay 속성값을 출력 HTML 의 video 태그에 전달하며, 실제 동작은 브라우저의 HTML5 video 처리에 따라 결정됩니다.",
        "속성을 한번이라도 설정하면 속성명이 유지되고, 속성명 정의만으로 해당 기능이 설정됩니다.",
        "따라서, 소스에서 직접 속성명을 제거해야 해당 기능이 해제됩니다."
    ]
}

// 화면 로딩 시점의 자동 재생 발생 여부 기록용
scwin.gPlayLog = { "target1" : false, "target2" : false, "target3" : false, "target4" : false };



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 화면 로딩 시 자동 재생(play) 발생 여부를 video 요소별로 기록
    ["target1", "target2", "target3", "target4"].forEach(function (sId) {
        let el = document.querySelector("#" + sId);
        if (el === null) return;
        el.addEventListener("play", function () { scwin.gPlayLog[sId] = true; });
    });
};



// 화면 로딩 이후 실제 자동 재생이 발생했는지 판정 (재생 종료 후 클릭한 경우 포함)
scwin.fn_isAutoPlayed = function (sId) {
    let el = document.querySelector("#" + sId);
    return scwin.gPlayLog[sId] === true || el.currentTime > 0 || el.ended === true;
};



// video 요소별 자동 재생 결과 확인
scwin.btn_getAutoplayResult_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let nAutoPlayed = (scwin.fn_isAutoPlayed("target1") ? 1 : 0) + (scwin.fn_isAutoPlayed("target2") ? 1 : 0);

    wf_body_bottom.getObj("scwin").setReturnValue("기본 차단 - 동영상 로드(readyState) : " + el1.readyState + " , 소리 포함 + autoplay 인 target1 과 target2 중 자동 재생된 개수 : " + nAutoPlayed + " / 2");
    wf_body_bottom.getObj("scwin").setReturnValue("autoplay 를 autoplay 로 설정 - 자동 재생 : " + scwin.fn_isAutoPlayed("target1"));
    wf_body_bottom.getObj("scwin").setReturnValue("autoplay 를 빈 문자열로 설정 - 자동 재생 : " + scwin.fn_isAutoPlayed("target2"));
    wf_body_bottom.getObj("scwin").setReturnValue("정책에 의한 차단 - target1 차단 여부 : " + (scwin.fn_isAutoPlayed("target1") === false && el1.paused === true));
    wf_body_bottom.getObj("scwin").setReturnValue("muted 설정 시 허용 - target3(muted) 자동 재생 : " + scwin.fn_isAutoPlayed("target3") + " , target1(muted 없음) 자동 재생 : " + scwin.fn_isAutoPlayed("target1"));
};



// 출력 HTML video 태그로 전달된 autoplay 속성값과 속성 유무에 따른 설정/해제 확인
scwin.btn_getAutoplayAttr_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let el3 = document.querySelector("#target3");
    let el4 = document.querySelector("#target4");

    wf_body_bottom.getObj("scwin").setReturnValue("출력 HTML 속성값 - target1 : " + JSON.stringify(el1.getAttribute("autoplay")) + " , target2 : " + JSON.stringify(el2.getAttribute("autoplay")) + " , target3 : " + JSON.stringify(el3.getAttribute("autoplay")) + " , target4 : " + JSON.stringify(el4.getAttribute("autoplay")));
    wf_body_bottom.getObj("scwin").setReturnValue("속성명만 정의 - target2 의 autoplay : " + el2.autoplay);
    wf_body_bottom.getObj("scwin").setReturnValue("속성 제거 - target4 의 autoplay : " + el4.autoplay);
};
